  f1(); // value of a: {}
  f1(1); // value of a: {1}
  f1(1,2,3); // value of a: {1,2,3}
  f3(); // ERROR: f3 requires a value for parameter a
  f3(100); // value of b: {}
  f3(100,1,2,3); // value of b: {1,2,3}
  f3(a := 10, b := {1,2,3}); // assignment notation
  f3(b := {1,2,3}, a := 10); // assignment notation
  f3(10, b := {1,2,3}); // mixed notation
  f6(); // value of a: 10, value of b: {1,2,3}
  f6(1); // value of a: 1, value of b: {1,2,3}
  f6(1,2); // value of a: 1, value of b: {2}
  f6(-) // value of a: 10, value of b: {1,2,3}
  f6(-,1) // value of a: 10, value of b: {1}
  f6(-,-) // value of a: 10, value of b: {1,2,3}
  f6(-,-,-) // ERROR: f6 has only two formal parameters to skip.
  var record of integer a := {1,2,3};
  f1(a...); // passing a record of parameter directly

